class _UniffiFfiConverterTypePhantomStream:
    @staticmethod
    def lift(value: int) -> PhantomStream:
        return PhantomStream._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: PhantomStream):
        if not isinstance(value, PhantomStream):
            raise TypeError("Expected PhantomStream instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: PhantomStream) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> PhantomStream:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: PhantomStream, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

